import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val st = StringTokenizer(br.readLine())
    val n = st.nextToken().toInt()
    val t = st.nextToken().toInt()

    var dp = Array(5) { Array(5) { Array(12) { LongArray(12) } } }
    for (a in 1..4) for (b in 1..4) if (a != b) dp[a][b][0][0]++

    for (pos in 3..n) {
        val nd = Array(5) { Array(5) { Array(12) { LongArray(12) } } }
        for (a in 1..4) for (b in 1..4) {
            if (a == b) continue
            for (h in 0..10) for (v in 0..10) {
                val c = dp[a][b][h][v]
                if (c == 0L) continue
                for (cc in 1..4) {
                    if (cc == b) continue
                    var nh = h
                    var nv = v
                    if (a < b && b > cc) nh++
                    if (a > b && b < cc) nv++
                    if (nh > 10 || nv > 10) continue
                    nd[b][cc][nh][nv] += c
                }
            }
        }
        dp = nd
    }

    var ans = 0L
    if (t - 1 >= 0) {
        for (a in 1..4) for (b in 1..4) ans += dp[a][b][t][t - 1]
    }
    println(ans)
}
